#!/usr/bin/env bash
# A proto field that reaches no surface is a field that was added for nothing.
#
# `apps/core/lib/stacks/gen/proto_json.ex` is GENERATED by `mix proto.sync`, so
# `Gen.<message>/1` always emits exactly the contract's fields. The
# hand-written serializers in `apps/core/lib/stacks_web/proto_json.ex` then
# narrow those maps with `Map.take`, and that narrowing is deliberate: a search
# hit does not need a description, a slim placement ref does not need reading
# progress.
#
# ⚠️ WHAT NOTHING CHECKED. Add a field to a proto message and the generated
# side carries it automatically — and every hand-written serializer silently
# drops it. `mix proto.sync --check` compares GENERATED files against what it
# would generate, so it cannot see a hand-written allowlist at all. The field
# exists in the contract, is emitted by codegen, reaches no client, and no test
# anywhere fails. That is this repository's dominant defect class — built but
# not wired — on the one path where the contract itself promises otherwise.
#
# WHY A BASELINE AND NOT A REASON PER FIELD. There are 101 (field, serializer)
# omissions today and almost all are legitimate narrowing. Demanding a written
# reason for each would produce 101 shallow reasons, which is worse than none
# because it reads as considered when it was not — and it is the same cry-wolf
# shape this project already rejected once, when an 18-name secrets denylist
# named eighteen non-defects.
#
# So the population is pinned instead. The baseline below is a statement of
# WHERE WE ARE, reviewable in a diff when it moves — not a blessing. The gate
# fails when the set GROWS, naming the new pair, which turns the next proto
# field addition into a decision; and it fails when the baseline holds an entry
# that no longer exists, so it cannot rot into a list nobody maintains.
set -uo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || echo .)"
cd "$REPO_ROOT" || exit 1

python3 - <<'PY'
import collections
import pathlib
import re
import sys

GEN_PATH = "apps/core/lib/stacks/gen/proto_json.ex"
HAND_PATH = "apps/core/lib/stacks_web/proto_json.ex"

# The omission set as it stands. Each entry is "serializer:field".
#
# To change it: run this gate, read what it names, and either carry the field
# in the serializer or add the pair here in the same commit. The diff is the
# record of that decision.
#
# ─────────────────────────────────────────────────────────────────────────────
# HAND-DERIVED GROUND TRUTH (recorded BEFORE the harvest regex was corrected, so
# the corrected harvest is validated against a set computed WITHOUT it).
#
# The boundary the gate sees: 13 PUBLIC multiline `def … do … end` serializers
# that call a `Gen.X`, over 9 emitters. It does NOT see `defp` helpers
# (`listing_book`, `listing_seller`), one-liner `def …, do:` serializers
# (`author_slim`, `author_bookshelf`), or the controllers' own `Map.take` sites
# (a different file). Every omission below was judged DATA-LOSING (a field a
# client needs that no other path supplies) or DELIBERATE (internal id,
# server-only/bookkeeping, listing surface, or re-supplied downstream via
# `Map.merge`/`Map.put`). All were DELIBERATE except the `book_placement`
# started_at/finished_at pair (DATA-LOSING — the progress card renders the date).
#
# `book_placement` (emitter `Gen.placement`, 23 fields) per-entry verdicts:
#   bookshelf_id ....... DELIBERATE  card shows bookshelf_name (merged), not the FK
#   position ........... DELIBERATE  shelf ordering, unused by the card
#   placed_at .......... DELIBERATE  not rendered
#   removed_at ......... DELIBERATE  soft-delete bookkeeping
#   formats ............ FALSE POS   re-supplied via Map.merge(%{formats:}) — the
#                                    `:atom` harvest missed the keyword key
#   visibility ......... FALSE POS   re-supplied via Map.merge(%{visibility:})
#   listing_* (4) ...... DELIBERATE  marketplace, a separate surface
#   created_at ......... DELIBERATE  bookkeeping
#   updated_at ......... DELIBERATE  bookkeeping
#   started_at ......... DATA-LOSING PlacementCard renders the date (bare "Finished"
#                                    without it on a page load) — carried now
#   finished_at ........ DATA-LOSING same (PlacementCard.elm:290) — carried now
#   shelf_id ........... DELIBERATE  physical-shelf FK
#   book_edition_id .... DELIBERATE  internal edition FK; formats cover display
#   source ............. DELIBERATE  placement provenance, unshown
#
# The corrected harvest therefore deletes exactly `book_placement:formats` and
# `book_placement:visibility` (keyword-key recognition); carrying started_at/
# finished_at in the serializer deletes those two as well. 102 → 98.
#
# Reconciliation with the issue's named false positives: `formats` CONFIRMED;
# `bookshelf_id` is NOT one (the merge supplies bookshelf_NAME, not the id — it
# stays a real DELIBERATE omission); `bookshelf_name` is not a `Gen.placement`
# field and was never in the baseline. `visibility` is the fourth false positive
# the issue did not name. Per the issue's rule, that disagreement is a finding,
# recorded here rather than reconciled away.
#
# ⚠️ SEPARATE FINDING, out of scope for the keyword fix: the `blog_association`
# serializer has NO `Map.take` — `Gen.book_association |> Map.merge(%{...})`
# carries ALL 8 book_association fields — so its 7 baseline entries are false
# positives too. They survive because the harvest models `carried = atoms in
# body`, which breaks for a serializer that narrows by NOT calling `Map.take`.
# Correcting that is a larger, different change (model "no Map.take ⇒ all Gen
# fields carried") and would overturn a documented in-file disposition; left for
# a follow-up.
# ─────────────────────────────────────────────────────────────────────────────
BASELINE = {
    "author:created_at",
    "author:open_library_id",
    "author:rss_feed_url",
    "author:updated_at",
    "blog_association:book_id",
    "blog_association:confidence",
    # ⚠️ `created_at` and `post_id` joined this baseline rather than staying
    # hidden. Both sat in the BookAssociation serializer's `skip_fields`, which
    # removes a field from the GENERATED shape — the left-hand side of this
    # script's set difference — so a declared proto field reaching no client was
    # invisible to the gate that exists to find exactly that. Found by the same
    # query that found `seller_id`, in the same class.
    #
    # Both are genuinely dropped: this serializer carries ONE field, the
    # `post_id` that `Types/FeedItem.elm` decodes comes from the feed-item
    # payload rather than this one, and `created_at` is server bookkeeping that
    # nothing reads. Neither is personal data, so a baseline row is the right
    # disposition — the sorting rule being that an unconsumed NON-personal field
    # is inventory, while an unconsumed PERSONAL field on a public payload is a
    # disclosure and a baseline row would pin the exposure as an accepted
    # omission.
    #
    # `book_title` and `status` remain skipped, correctly and for a different
    # reason: they are derived values the hand-written serializer computes, so
    # codegen emitting `struct.book_title` would emit a column that does not
    # exist.
    "blog_association:created_at",
    "blog_association:post_id",
    "blog_association:id",
    "blog_association:source",
    "blog_association:visible",
    "blog_post:visibility_group_id",
    "book:author_id",
    # Removed from the detail payload 2026-10-20, each on a measurement rather
    # than a preference: `language` is written by seeds.exs and nothing else (169
    # of 169 local rows "en", 55 of 55 production rows NULL), and `bisac_codes`
    # already reaches its only consumer through the insights endpoint while the
    # reader-facing form on a book page is `subjects`. Both were dropped by the
    # SPA's hand-written adapter anyway, so no client lost anything.
    "book:bisac_codes",
    "book:created_at",
    "book:language",
    "book:updated_at",
    "book_placement:book_edition_id",
    "book_placement:bookshelf_id",
    "book_placement:created_at",
    "book_placement:listing_min_price_cents",
    "book_placement:listing_mode",
    "book_placement:listing_price_cents",
    "book_placement:listing_status",
    "book_placement:placed_at",
    "book_placement:position",
    "book_placement:removed_at",
    "book_placement:shelf_id",
    "book_placement:source",
    "book_placement:updated_at",
    # `user_id` is DB-only on every placement serializer: the denormalised owner
    # added so the row-level policy is an indexable `user_id = current_scope()`,
    # never put on the wire — no client needs it, exactly like book_edition_id. A
    # deliberate omission across book_placement/placement_detail/placement_ref.
    "book_placement:user_id",
    "bookshelf_book:author_id",
    "bookshelf_book:bisac_codes",
    "bookshelf_book:created_at",
    "bookshelf_book:language",
    "bookshelf_book:subjects",
    "bookshelf_book:updated_at",
    "catalogue_book:author_id",
    "catalogue_book:bisac_codes",
    "catalogue_book:created_at",
    "catalogue_book:description",
    "catalogue_book:language",
    "catalogue_book:updated_at",
    # Same class as the two above and as `listing:seller_id`: previously hidden
    # by `skip_fields` rather than recorded. Nothing consumes `edition.book_id`
    # — the `book_id` that `Api.elm` decodes belongs to the upload payload — and
    # an edition is always nested under its book, so the parent id is already in
    # hand.
    "edition:book_id",
    "edition:created_at",
    "edition:google_books_id",
    "edition:open_library_id",
    "edition:updated_at",
    "listing:book_id",
    # `seller_id` joined this baseline rather than being hidden from the gate.
    # It used to sit in the Listing serializer's `skip_fields`, which removes a
    # field from the GENERATED shape — the left-hand side of this script's set
    # difference — so a declared proto field reaching no client was invisible to
    # the gate that exists to find exactly that. `book_id` beside it was never
    # skipped and has always been pinned here, and the asymmetry had no reason.
    # Both are genuinely dropped: nothing in Elm or e2e references either, and
    # `seller_id` is redundant with `seller.id` on the projection. The point is
    # that "dropped on purpose" is now recorded where a reader will see it,
    # instead of being achieved by making the field unobservable.
    "listing:seller_id",
    "placement_detail:book_edition_id",
    "placement_detail:book_id",
    "placement_detail:bookshelf_id",
    "placement_detail:created_at",
    "placement_detail:listing_min_price_cents",
    "placement_detail:listing_mode",
    "placement_detail:listing_price_cents",
    "placement_detail:listing_status",
    "placement_detail:removed_at",
    "placement_detail:shelf_id",
    "placement_detail:source",
    "placement_detail:updated_at",
    "placement_detail:user_id",
    "placement_ref:book_edition_id",
    "placement_ref:created_at",
    "placement_ref:current_page",
    "placement_ref:finished_at",
    "placement_ref:formats",
    "placement_ref:listing_min_price_cents",
    "placement_ref:listing_mode",
    "placement_ref:listing_price_cents",
    "placement_ref:listing_status",
    "placement_ref:notes",
    "placement_ref:personal_rating",
    "placement_ref:reading_status",
    "placement_ref:source",
    "placement_ref:started_at",
    "placement_ref:updated_at",
    "placement_ref:user_id",
    "placement_ref:visibility",
    "search_book:author_id",
    "search_book:bisac_codes",
    "search_book:created_at",
    "search_book:description",
    "search_book:language",
    "search_book:subjects",
    "search_book:updated_at",
    "user:age_verification_provider",
    "user:age_verified_at",
    "user:consent_analytics_at",
    # `user:consent_writing_assistant` was here and is GONE because the field is
    # now carried. It was a real data-losing omission, not a deliberate one: the
    # client already decoded it, and a proto3 bool's implicit presence turned the
    # absence into a stored `false` — withdrawing a GDPR consent on a save that
    # raced the settings fetch. The `_at` timestamp below stays omitted, which is
    # correct: nothing reads it and it is the server's own bookkeeping.
    "user:consent_writing_assistant_at",
    # Same as the two consent timestamps above: the opt-in bool is serialized,
    # its `_at` is the server's own bookkeeping and nothing reads it.
    "user:consent_search_indexing_at",
    "user:created_at",
    "user:email_confirmed",
    "user:notify_event_matches",
    "user:notify_group_invitations",
    "user:notify_marketplace",
    "user:notify_wishlist_availability",
    "user:onboarding_steps",
    "user:syndication_default",
    "user:updated_at",
}


# ⛔ COMMENTS ARE NOT CODE, and this gate learned that the hard way — from a
# comment written to EXPLAIN a removal, which then hid it.
#
# The carried-field harvest below regexes `:atom` out of a serializer's body. A
# comment saying why `:language` was dropped spells `:language`, so the harvest
# counted the field as still carried and the gate reported 98 omissions, all
# pinned, over a payload that had just lost two fields. A green run for a change
# the gate exists to notice.
#
# ⚠️ This is the same defect class the repository already records five instances
# of, arrived at from the other direction: there, an ABSENCE assertion matched
# the prose explaining why a pattern was banned; here, a PRESENCE harvest
# matched the prose explaining why a field was removed. Both are a gate reading
# its own documentation as configuration.
#
# Elixir has no block comments, so `#` to end of line is the whole job — but
# `#{` is interpolation, not a comment, and stripping from it would eat live
# code. A `#` inside a string is left alone for the same reason: the harvest
# only cares about atoms, and an atom inside a string is not a carried field
# either way.
def _strip_comments(src):
    out = []
    for line in src.split("\n"):
        cleaned = []
        in_string = False
        i = 0
        while i < len(line):
            ch = line[i]
            if ch == '"':
                in_string = not in_string
            elif ch == "#" and not in_string:
                # `#{` is interpolation and keeps its line.
                if i + 1 < len(line) and line[i + 1] == "{":
                    cleaned.append(line[i:])
                    i = len(line)
                    continue
                break
            cleaned.append(ch)
            i += 1
        out.append("".join(cleaned))
    return "\n".join(out)


# ⚠️ WHAT THE `:atom` HARVEST MISSED, and why this exists.
#
# `carried` below is seeded from `:atom` literals — the form a `Map.take` list
# and a `Map.put(map, :key, …)` use. But a field re-supplied through
# `Map.merge(%{field: value})` is written as a KEYWORD KEY (`field:`, colon
# after), which `:([a-z_0-9]+)` never matches. So `book_placement`, which
# carries `formats` and `visibility` through exactly such a merge, had both
# reported as DROPPED — present on the wire, pinned in the baseline as omitted.
# An inventory wrong in the over-reporting direction is the noise that stops the
# gate being read, which is the whole reason it exists.
#
# ⛔ A naive `\b(\w+):` union is the wrong fix: it also matches `do:`, `else:`,
# `into:` and friends, and each false match would DELETE a baseline entry that
# should stay — shrinking the set in the wrong direction while looking like
# progress. Two guards keep that from happening: keys are read ONLY from inside
# `%{…}` map literals (brace-balanced), and ONLY when they begin a line
# (map keys in this file are formatted one per line). The `do:`/`else:` inside
# an `if(… , do: …, else: …)` VALUE sit mid-line, so they are never read. A
# small deny-list of Elixir keyword atoms is carried as a third belt.
_KEYWORD_DENYLIST = {
    "do",
    "else",
    "end",
    "after",
    "catch",
    "rescue",
    "when",
    "for",
    "into",
    "fn",
    "if",
    "unless",
}


def _map_literal_keys(src):
    """Keyword keys that begin a line inside a `%{…}` map literal.

    These are fields a serializer ADDS via `Map.merge`/`Map.put(map, %{…})`.
    Counting them as carried is what stops a re-supplied field being reported as
    dropped. Scoped to `%{…}` spans so a stray `label:` elsewhere cannot delete
    a baseline entry.
    """
    keys = set()
    i = 0
    n = len(src)
    while i < n:
        if src[i : i + 2] == "%{":
            depth = 1
            j = i + 2
            start = j
            while j < n and depth > 0:
                if src[j] == "{":
                    depth += 1
                elif src[j] == "}":
                    depth -= 1
                j += 1
            span = src[start : j - 1]
            for line in span.split("\n"):
                m = re.match(r"\s*([a-z_][a-z_0-9]*):", line)
                if m and m.group(1) not in _KEYWORD_DENYLIST:
                    keys.add(m.group(1))
            i = j
        else:
            i += 1
    return keys


def read(path):
    try:
        return pathlib.Path(path).read_text(encoding="utf-8")
    except OSError as exc:
        print(f"FAIL: cannot read {path}: {exc}", file=sys.stderr)
        print(
            "This gate compares GENERATED serializers against hand-written ones. The generated\n"
            "half is produced by `mix proto.sync`, so on a fresh clone run that first — this is a\n"
            "refusal, not a pass.",
            file=sys.stderr,
        )
        raise SystemExit(1)


gen_src = read(GEN_PATH)
hand_src = read(HAND_PATH)

# Module-attribute field lists, resolved so a serializer using `@user_auth_fields`
# is not reported as omitting everything in it. Without this the `user`
# serializer alone showed 29 phantom omissions instead of its real 14.
attrs = {}
for match in re.finditer(r"@([a-z_]+)\s+\[([^\]]*)\]", hand_src, re.S):
    attrs[match.group(1)] = set(re.findall(r":([a-z_0-9]+)", match.group(2)))
for match in re.finditer(r"@([a-z_]+)\s+@([a-z_]+)\s*\+\+\s*\[([^\]]*)\]", hand_src, re.S):
    attrs[match.group(1)] = attrs.get(match.group(2), set()) | set(
        re.findall(r":([a-z_0-9]+)", match.group(3))
    )

# What each generated serializer emits — the contract's field set for that message.
gen_fields = {}
# The emitting SOURCE LINE for each generated field, kept so a failure can show
# what codegen actually wrote rather than only the field's name. See the FAIL
# block below for why that turned out to matter.
gen_lines = {}
for match in re.finditer(r"\n  def ([a-z_]+)\(struct\) do\n    %\{(.*?)\n    \}", gen_src, re.S):
    body = match.group(2)
    gen_fields[match.group(1)] = set(re.findall(r"^\s+([a-z_0-9]+):", body, re.M))
    for line in body.split("\n"):
        m = re.match(r"^\s+([a-z_0-9]+):", line)
        if m:
            gen_lines[(match.group(1), m.group(1))] = line.strip().rstrip(",")

# ⚠️ Anti-vacuity on both populations. Every comparison below is a set
# difference, which is empty when everything is correct AND when nothing was
# parsed — so a drifted regex would report a clean pass over nothing. These are
# the two numbers that make the result mean anything.
if len(gen_fields) < 5:
    print(
        f"FAIL: parsed only {len(gen_fields)} generated serializer(s) from {GEN_PATH}.",
        file=sys.stderr,
    )
    print(
        "That file defines one per persisted proto message, so a number this low means the\n"
        "parse stopped matching its shape rather than that the messages are gone.",
        file=sys.stderr,
    )
    raise SystemExit(1)

omissions = set()
operands = {}
narrowing = 0
for match in re.finditer(r"\n  def ([a-z_]+)\(([^)]*)\) do\n(.*?)\n  end\n", hand_src, re.S):
    name, body = match.group(1), match.group(3)
    gen_call = re.search(r"Gen\.([a-z_]+)\(", body)
    if not gen_call or gen_call.group(1) not in gen_fields:
        continue
    narrowing += 1
    stripped = _strip_comments(body)
    # `:atom` literals (Map.take lists, Map.put atom keys) PLUS keyword keys of
    # `%{…}` map literals (Map.merge/Map.put additions). The second half is the
    # fix: without it a merged-in field reads as dropped. See `_map_literal_keys`.
    carried = set(re.findall(r":([a-z_0-9]+)", stripped))
    carried |= _map_literal_keys(stripped)
    for attr in re.findall(r"@([a-z_]+)", body):
        carried |= attrs.get(attr, set())
    operands[name] = (gen_call.group(1), gen_fields[gen_call.group(1)], carried)
    for field in gen_fields[gen_call.group(1)] - carried:
        omissions.add(f"{name}:{field}")

if narrowing < 5:
    print(
        f"FAIL: found only {narrowing} hand-written serializer(s) narrowing a Gen call "
        f"in {HAND_PATH}.",
        file=sys.stderr,
    )
    print(
        "This gate exists because those serializers drop fields silently; finding almost none\n"
        "means the parse is not reading them, not that they stopped narrowing.",
        file=sys.stderr,
    )
    raise SystemExit(1)

added = sorted(omissions - BASELINE)
stale = sorted(BASELINE - omissions)
failed = False

if added:
    failed = True
    print(
        f"FAIL: {len(added)} proto field(s) reach no client through their serializer:",
        file=sys.stderr,
    )
    by_serializer = collections.defaultdict(list)
    for pair in added:
        serializer, field = pair.split(":", 1)
        by_serializer[serializer].append(field)
    # ⛔ NAME BOTH SETS, NOT THE DIFFERENCE.
    #
    # This used to print only `listing drops seller` — a set difference naming
    # neither operand. That line was produced for a REAL defect (codegen was
    # emitting `seller: struct.seller`, the raw Ecto association) and was very
    # nearly dismissed as a known false positive of this script's own harvest
    # regex, which does miss keyword keys supplied via `Map.merge`. Both
    # explanations fit the message equally well, because the message carried no
    # evidence to tell them apart.
    #
    # The generated line is the evidence. `seller: struct.seller` in the error
    # text says at a glance that the generated side emits the association
    # itself, which no amount of knowing about the regex would have suggested.
    for serializer, fields in sorted(by_serializer.items()):
        gen_name, gen_set, carried_set = operands.get(serializer, (serializer, set(), set()))
        print(f"  {serializer:<22} drops {', '.join(sorted(fields))}", file=sys.stderr)
        print(
            f"    generated Gen.{gen_name}/1 emits {len(gen_set)} field(s); "
            f"the hand-written {serializer}/1 carries {len(carried_set)}",
            file=sys.stderr,
        )
        for field in sorted(fields):
            line = gen_lines.get((gen_name, field))
            if line:
                print(f"    codegen wrote: {line}", file=sys.stderr)
        print("", file=sys.stderr)
    print(
        "\nThe generated side carries every contract field automatically; a hand-written\n"
        "allowlist does not. So a field added to the proto is emitted by codegen, dropped\n"
        "here, and reaches nothing — with no test failing, because `mix proto.sync --check`\n"
        "only compares generated files against generated files.\n\n"
        "There are THREE dispositions, and the first is easy to miss:\n\n"
        "  1. The field MUST NEVER be serialized — a credential, a single-use token.\n"
        "     Then both options below are wrong, and `skip_fields` in proto/persisted.exs\n"
        "     is the right place for it. `check-never-serialized.sh` is what enforces that;\n"
        "     this gate has nothing useful to say about such a field.\n"
        "  2. A client needs it — carry it in the serializer.\n"
        "  3. It is deliberately dropped and harmless — add the pair to BASELINE in this\n"
        "     script in the same commit. The diff is the record that somebody decided.\n\n"
        "⛔ Option 1 is listed first because this message used to offer only 2 and 3, and\n"
        "MEASURED: deleting `:password_hash` from the User entry's skip_fields made this gate\n"
        "print `user drops password_hash` followed by `Either carry the field ... or add the\n"
        "pair to BASELINE`. Following either instruction would have serialized an Argon2 hash\n"
        "to clients or pinned it as an accepted omission. A gate whose remediation advice is\n"
        "wrong on the worst field it can report is worse than one that stays quiet.",
        file=sys.stderr,
    )

if stale:
    failed = True
    print(
        f"FAIL: {len(stale)} BASELINE entr(ies) name an omission that no longer exists:",
        file=sys.stderr,
    )
    for pair in stale:
        print(f"  {pair}", file=sys.stderr)
    print(
        "\nThe field is carried now, or the serializer is gone. Remove the entry — a baseline\n"
        "that keeps entries for nothing is how it stops describing the code.",
        file=sys.stderr,
    )

if not failed:
    print(
        f"OK: {narrowing} serializer(s) narrow {len(gen_fields)} generated shape(s); "
        f"{len(omissions)} omission(s), all pinned."
    )

raise SystemExit(1 if failed else 0)
PY
